from fastapi import APIRouter, HTTPException
from uuid import uuid4
from datetime import datetime
from ..models import MessageRequest, ConversationCreate
from ..agents.graph import build_graph

router = APIRouter(prefix="/api/conversations", tags=["conversations"])
conversations = {}
graph = build_graph()

@router.post("", status_code=201)
async def create_conversation(data: ConversationCreate):
    conv_id = str(uuid4())
    conversations[conv_id] = {
        "id": conv_id, "messages": [],
        "current_agent": "", "status": "active",
        "created_at": datetime.utcnow(),
    }
    return conversations[conv_id]

@router.post("/{conv_id}/messages")
async def send_message(conv_id: str, msg: MessageRequest):
    if conv_id not in conversations:
        raise HTTPException(status_code=404, detail="Conversation not found")
    conv = conversations[conv_id]
    conv["messages"].append({"role": msg.role, "content": msg.content})
    result = await graph.ainvoke({
        "messages": conv["messages"], "current_agent": conv["current_agent"],
        "intent": "", "confidence": 0.0, "context": {},
        "customer_sentiment": 3, "attempted_solutions": [], "escalation_reason": None,
    })
    assistant_msg = result["messages"][-1]
    conv["messages"].append(assistant_msg)
    conv["current_agent"] = result.get("current_agent", "")
    return {"response": assistant_msg, "agent": result.get("intent", "")}

@router.get("/{conv_id}")
async def get_conversation(conv_id: str):
    if conv_id not in conversations:
        raise HTTPException(status_code=404, detail="Conversation not found")
    return conversations[conv_id]

@router.get("")
async def list_conversations():
    return list(conversations.values())

