async def tech_agent(state: AgentState) -> dict:
    query = state["messages"][-1]["content"]
    attempted = state.get("attempted_solutions", [])
    context = ""
    if attempted:
        context = f"\nDaha önce denenen çözümler:\n" + "\n".join(f"- {s}" for s in attempted)
    response = await llm.ainvoke([SystemMessage(content=TECH_SYSTEM_PROMPT), HumanMessage(content=f"Sorun: {query}{context}\nBir sonraki adımı öner.")])
