    if len(new_attempted) >= 5:
        return {"current_agent": "tech", "intent": "escalation", "attempted_solutions": new_attempted,
                "escalation_reason": "5 adım sonra çözülemedi",
                "messages": [{"role": "assistant", "content": response.content + "\n\nSorununuz devam ediyorsa sizi uzman ekibimize yönlendiriyorum."}]}
    return {"current_agent": "tech", "attempted_solutions": new_attempted,
            "messages": [{"role": "assistant", "content": response.content}]}

def route_decision(state: AgentState) -> str:
    intent = state.get("intent", "escalation")
    confidence = state.get("confidence", 0.0)
    sentiment = state.get("customer_sentiment", 3)
    if confidence < 0.7:
        return "escalation"
    if sentiment <= 2:
        return "escalation"
    intent_map = {"faq": "faq", "technical": "tech", "billing": "escalation", "escalation": "escalation"}
    return intent_map.get(intent, "escalation")

