import json
from pathlib import Path
from typing import List
from dataclasses import dataclass
from datetime import datetime

@dataclass
class DocumentChunk:
    content: str
    metadata: dict
    chunk_id: str

def chunk_markdown(text: str, source: str, max_tokens: int = 400) -> List[DocumentChunk]:
    sections = []
    current_section = ""
    current_heading = ""
    for line in text.split("\n"):
        if line.startswith("#"):
            if current_section.strip():
                sections.append((current_heading, current_section.strip()))
            current_heading = line.strip("# ").strip()
            current_section = line + "\n"
        else:
            current_section += line + "\n"
    if current_section.strip():
        sections.append((current_heading, current_section.strip()))
    chunks = []
    for i, (heading, content) in enumerate(sections):
        chunks.append(DocumentChunk(content=content, metadata={"source": source, "heading": heading, "chunk_index": i, "last_updated": datetime.utcnow().isoformat()}, chunk_id=f"{source}_{i}"))
    return chunks

def load_knowledge_base(kb_dir: str) -> List[DocumentChunk]:
    all_chunks = []
    kb_path = Path(kb_dir)
    for md_file in kb_path.glob("*.md"):
        text = md_file.read_text(encoding="utf-8")
        chunks = chunk_markdown(text, source=md_file.stem)
        all_chunks.extend(chunks)
    return all_chunks

import chromadb
from typing import List
from .document_processor import DocumentChunk, load_knowledge_base

class VectorStore:
    def __init__(self, persist_dir: str = "./chroma_db"):
        self.client = chromadb.Client()
        self.collection = self.client.get_or_create_collection(name="knowledge_base", metadata={"hnsw:space": "cosine"})

    def add_documents(self, chunks: List[DocumentChunk]):
        self.collection.add(documents=[c.content for c in chunks], metadatas=[c.metadata for c in chunks], ids=[c.chunk_id for c in chunks])

    def search(self, query: str, top_k: int = 3) -> list:
        results = self.collection.query(query_texts=[query], n_results=top_k)
        return [{"content": doc, "metadata": meta, "score": 1 - dist}
                for doc, meta, dist in zip(results["documents"][0], results["metadatas"][0], results["distances"][0])]

    def initialize_from_directory(self, kb_dir: str):
        chunks = load_knowledge_base(kb_dir)
        if chunks:
            self.add_documents(chunks)
        return len(chunks)

vector_store = VectorStore()

