from rank_bm25 import BM25Okapi
from .vector_store import vector_store
from .document_processor import load_knowledge_base

class HybridRetriever:
    def __init__(self):
        self.chunks = []
        self.bm25 = None

    def initialize(self, kb_dir: str):
        self.chunks = load_knowledge_base(kb_dir)
        tokenized = [c.content.lower().split() for c in self.chunks]
        self.bm25 = BM25Okapi(tokenized)
        vector_store.initialize_from_directory(kb_dir)

    def search(self, query: str, top_k: int = 5) -> List[Dict]:
        dense_results = vector_store.search(query, top_k=top_k)
        sparse_results = []
        if self.bm25 and self.chunks:
            scores = self.bm25.get_scores(query.lower().split())
            sparse_results = sorted([{"content": self.chunks[i].content, "metadata": self.chunks[i].metadata, "score": float(s)} for i, s in enumerate(scores)], key=lambda x: x["score"], reverse=True)[:top_k]
        return self._rrf_merge(dense_results, sparse_results, top_k)

    def _rrf_merge(self, dense, sparse, top_k, k=60):
        scores = {}
        data = {}
        for rank, r in enumerate(dense):
            key = r["content"][:100]
            scores[key] = scores.get(key, 0) + 1/(k+rank+1)
            data[key] = r
        for rank, r in enumerate(sparse):
            key = r["content"][:100]
            scores[key] = scores.get(key, 0) + 1/(k+rank+1)
            if key not in data: data[key] = r
        results = []
        for key in sorted(scores, key=scores.get, reverse=True)[:top_k]:
            d2 = data[key].copy()
            d2["rrf_score"] = scores[key]
            results.append(d2)
        return results

