async def get_intent_distribution(self) -> Dict:
    events = await self.redis.lrange("analytics:events", 0, 999)
    intents = {}
    for e in events:
        event = json.loads(e)
        if event["type"] == "message_sent":
            intent = event["data"].get("agent", "unknown")
            intents[intent] = intents.get(intent, 0) + 1
    return dict(sorted(intents.items(), key=lambda x: x[1], reverse=True))

async def get_avg_conversation_length(self) -> float:
    events = await self.redis.lrange("analytics:events", 0, 999)
    conv_lengths = {}
    for e in events:
        event = json.loads(e)
        if event["type"] == "message_sent":
            cid = event["data"].get("conv_id", "")
            conv_lengths[cid] = conv_lengths.get(cid, 0) + 1
    return sum(conv_lengths.values()) / max(len(conv_lengths), 1)

