const WebSocket = require('ws');
const http = require('http');
const { v4: uuidv4 } = require('uuid');
require('dotenv').config();

const server = http.createServer();
const wss = new WebSocket.Server({ server });
const ORCHESTRATOR_URL = process.env.ORCHESTRATOR_URL || 'http://localhost:8000';
const connections = new Map();

wss.on('connection', (ws) => {
  const clientId = uuidv4();
  connections.set(clientId, { ws, convId: null });
  ws.isAlive = true;
  ws.on('pong', () => { ws.isAlive = true; });
  ws.on('message', async (data) => {
    try {
      const msg = JSON.parse(data);
      if (msg.type === 'start_conversation') {
        const res = await fetch(`${ORCHESTRATOR_URL}/api/conversations`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: '{}' });
        const conv = await res.json();
        connections.get(clientId).convId = conv.id;
        ws.send(JSON.stringify({ type: 'conversation_started', data: conv }));
      } else if (msg.type === 'send_message') {
        const convId = connections.get(clientId)?.convId;
        if (!convId) { ws.send(JSON.stringify({type:'error',message:'No conversation'})); return; }
        const res = await fetch(`${ORCHESTRATOR_URL}/api/conversations/${convId}/messages`, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify({content: msg.content}) });
        ws.send(JSON.stringify({ type: 'agent_response', data: await res.json() }));
      }
    } catch (err) { ws.send(JSON.stringify({type:'error',message:err.message})); }
  });
  ws.on('close', () => connections.delete(clientId));
});

setInterval(() => { wss.clients.forEach(ws => { if (!ws.isAlive) return ws.terminate(); ws.isAlive = false; ws.ping(); }); }, 30000);

server.listen(process.env.PORT || 3001, () => console.log('WS Gateway running'));

import { useEffect, useRef, useState, useCallback } from 'react';

export function useWebSocket(url: string) {
  const wsRef = useRef<WebSocket | null>(null);
  const [isConnected, setIsConnected] = useState(false);
  const [messages, setMessages] = useState<any[]>([]);
  const reconnectRef = useRef<NodeJS.Timeout>();

  const connect = useCallback(() => {
    const ws = new WebSocket(url);
    wsRef.current = ws;
    ws.onopen = () => setIsConnected(true);
    ws.onmessage = (e) => setMessages(prev => [...prev, JSON.parse(e.data)]);
    ws.onclose = () => { setIsConnected(false); reconnectRef.current = setTimeout(connect, 3000); };
    ws.onerror = (err) => console.error('WS error:', err);
  }, [url]);

  useEffect(() => { connect(); return () => { clearTimeout(reconnectRef.current); wsRef.current?.close(); }; }, [connect]);

  const send = useCallback((msg: any) => {
    if (wsRef.current?.readyState === WebSocket.OPEN) wsRef.current.send(JSON.stringify(msg));
  }, []);

  return { isConnected, messages, send };
}

import logging, json
from datetime import datetime

class JSONFormatter(logging.Formatter):
    def format(self, record):
        return json.dumps({"timestamp": datetime.utcnow().isoformat(), "level": record.levelname,
                          "message": record.getMessage(), "module": record.module})

def setup_logging():
    handler = logging.StreamHandler()
    handler.setFormatter(JSONFormatter())
    logging.basicConfig(level=logging.INFO, handlers=[handler])
